STAGE_CAP={'Request':'What the customer submits.','Understand':'What the workflow classifies, without pretending to diagnose.','Act':'Who is alerted and the immediate human action.','Progress':'The job, appointment, estimate or order record.','Continue':'The next useful follow-up, repeat service or customer update.'}
DEFAULT_LABEL={'Progress':'Work record','Continue':'Next action','Request':'New enquiry','Understand':'Classified','Act':'Owner alert'}
def J(stage,label,*rest):
    if len(rest)==2: title=label; label=DEFAULT_LABEL[stage]; lines=list(rest)
    else: title=rest[0]; lines=list(rest[1:3])
    while len(lines)<2: lines.append('')
    return dict(stage=stage,label=label,title=title,lines=lines,actions=ACTS[stage])

