def menu(root=''):
    items=''.join(f'<a href="{root}{u["slug"]}.html">{ICON[u["slug"]]}{u["label"]}</a>' for u in UC)
    items+=f'<a href="{root}creators.html">{ICON["creators"]}Creators with expertise</a>'
    return f'<div class="has-menu"><a href="{root}index.html#usecases" class="uc-toggle">Use cases</a><div class="menu" role="menu">{items}<a class="all" href="{root}index.html#usecases">See all use cases</a></div></div>'
