def demo_block(u):
    d=u['demo']; slug=u['slug']
    inputs=f'<div class="fld"><label for="{slug}-name">Your name</label><input id="{slug}-name" data-f="name" value="{E(d["name"])}"></div>'
    for fld in d['fields']:
        fid,label,typ,opts,ex=fld[:5]; show=fld[5] if len(fld)>5 else None
        attr=f' data-show="{E(show)}"' if show else ''
        if typ=='select':
            o=''.join(f'<option{" selected" if x==ex else ""}>{E(x)}</option>' for x in opts)
            inputs+=f'<div class="fld"{attr}><label for="{slug}-{fid}">{E(label)}</label><select id="{slug}-{fid}" data-f="{fid}">{o}</select></div>'
        else:
            inputs+=f'<div class="fld"{attr}><label for="{slug}-{fid}">{E(label)}</label><input id="{slug}-{fid}" data-f="{fid}" value="{E(ex)}"></div>'
    cfg=dict(mode='business',ack=['Thanks, {name}. We have your request.','A named person will be in touch with a real time, not "shortly".'],alert=list(d['alert']),reply=d['reply'],record=list(d['record']),remember=list(d['remember']),rules=d.get('rules',[]))
    wait='Your sample will appear here as the owner alert, the reply draft and the work record.'
    return f'''<section id="try"><div class="wrap"><p class="eyebrow">Try it</p><h2>Run a sample {E(u['label'].lower())} enquiry. Watch what your team would see.</h2><p class="sub">This runs in your browser only. Nothing is submitted, stored or sent. Change any value, then run it.</p>
<div class="demo"><form class="dform" data-demo="{slug}" data-cfg='{E(json.dumps(cfg,ensure_ascii=False),quote=True)}' onsubmit="return false"><h3>Sample form: {E(u['journey'][0]['title'])}</h3><p class="sub">The fields your customer would see.</p>{inputs}<button type="button" class="go">Run sample</button><button type="button" class="reset" style="display:none">Reset</button></form>
<div class="dout" data-wait="{wait}"><div class="dwait">{wait}</div></div></div>{ILLUS}</div></section>'''
